 def ReadFile():
    global DataArray
    try:
      TextFile = "IntegerData.txt"
      File = open(TextFile, 'r')
      for X in range(0, 100):
           DataArray[X] = File.readline()
           DataArray[X].rstrip('\n')
           DataArray[X] = int(DataArray[X])
      File.close()
    except IOError:
      print("Count not find file")
