 def CalculateValue(Player):
      Score = 0
      for Count in range(0, 4):
           CardGot = Player.GetCard(Count)
           Score = Score + CardGot.GetNumber()
           Colour = CardGot.GetColour()
           if Colour == "red":
                Score = Score + 5
           elif Colour == "blue":
                Score = Score + 10
           else:
                Score = Score + 15
      return Score
 Java
 public static Integer CalculateValue(Hand Player){
    Integer Score = 0;
    String Colour;
    Card CardGot;
    for(Integer X = 0; X<5; X++){
      CardGot = Player.GetCard(X);
      Score = Score + CardGot.GetNumber();
      Colour = CardGot.GetColour();
      if(Colour == "red"){
         Score = Score + 5;
      }else if(Colour == "blue"){
         Score = Score + 10;
      } else {
         Score = Score + 15;
      }}return Score;}
 VB.NET
 Function CalculateValue(Player As Hand)
    Dim Score As Integer = 0
    Dim Colour As String
    Dim CardGot As Card
    For Count = 0 To 4
      CardGot = Player.GetCard(Count)
      Score = Score + CardGot.GetNumber()
      Colour = CardGot.GetColour()
      If Colour = "red" Then
         Score = Score + 5
      ElseIf Colour = "blue" Then
         Score = Score + 10
      Else
         Score = Score + 15
      End If
    Next
    Return Score
 End Function

